
const D=JSON.parse(document.getElementById('project-data').textContent);let index=0,activeTab='deck',showNotes=false;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function render(){ $$('.slide').forEach((e,i)=>{e.classList.toggle('active',i===index);e.setAttribute('aria-hidden',i!==index)});$('#counter').textContent=`${index+1} / ${D.slides.length}`;$('#bar').style.width=`${(index+1)/D.slides.length*100}%`;$('#prev').disabled=index===0;$('#next').disabled=index===D.slides.length-1;$('#notes-body').textContent=D.slides[index].notes;$('#notes').hidden=!showNotes;$('#notes-toggle').setAttribute('aria-pressed',showNotes);$('#status').textContent=`第 ${index+1} 頁：${D.slides[index].title.replace(/<br>/g,'')}`;}
function setSlide(n){index=Math.max(0,Math.min(D.slides.length-1,n));render();history.replaceState(null,'',`#slide-${index+1}`)}
function tab(name){activeTab=name;$$('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==name);$$('nav [data-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tab===name));$('#overview').hidden=true;if(name!=='deck')window.scrollTo(0,0)}
function source(id){tab('wiki');$('#search').value='';searchWiki('');const el=document.getElementById('source-'+id);if(el){el.open=true;el.scrollIntoView({block:'center',behavior:'auto'});el.querySelector('summary').focus()}}
function searchWiki(q){const vocab=[...new Set(D.wiki.flatMap(e=>e.tags))];let terms=vocab.filter(t=>q.toLowerCase().includes(t.toLowerCase())).map(t=>t.toLowerCase());Object.entries(D.aliases).forEach(([k,v])=>{if(q.includes(k))terms.push(v.toLowerCase())});if(!terms.length&&q.trim())terms=[q.trim().toLowerCase()];let hits=0;D.wiki.forEach(e=>{const text=[e.title,e.body,...e.tags].join(' ').toLowerCase(),ok=!q.trim()||terms.some(t=>text.includes(t));$('#wiki-'+e.id).hidden=!ok;if(ok)hits++});$('#search-status').textContent=q.trim()?`找到 ${hits} 篇條目。${hits?'':'請換用端點、身分、網路、ARR 等概念，或先補充來源。'}`:'顯示全部六篇 Wiki 條目。';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-source],[data-wiki],[data-goto]');if(!b)return;e.preventDefault();if(b.dataset.tab)tab(b.dataset.tab);if(b.dataset.source)source(b.dataset.source);if(b.dataset.wiki){tab('wiki');$('#search').value='';searchWiki('');document.getElementById('wiki-'+b.dataset.wiki)?.scrollIntoView({block:'center'})}if(b.dataset.goto!==undefined){tab('deck');setSlide(Number(b.dataset.goto))}});
$('#prev').onclick=()=>setSlide(index-1);$('#next').onclick=()=>setSlide(index+1);$('#notes-toggle').onclick=()=>{showNotes=!showNotes;render()};$('#print').onclick=()=>window.print();$('#overview-toggle').onclick=()=>{$('#overview').hidden=!$('#overview').hidden};$('#search').oninput=e=>searchWiki(e.target.value);
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey)return;if(activeTab!=='deck')return;if(['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();setSlide(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();setSlide(index-1)}if(e.key==='Home'){e.preventDefault();setSlide(0)}if(e.key==='End'){e.preventDefault();setSlide(D.slides.length-1)}if(e.key.toLowerCase()==='n'&&!e.target.matches('button,a')){showNotes=!showNotes;render()}});
$$('.quiz button').forEach(b=>b.onclick=()=>{const q=b.closest('.quiz'),right=b.dataset.answer==='right';q.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));q.querySelector('.feedback').textContent=(right?'答對了。':'再想一下。')+(q.dataset.q==='1'?'驗證確認身分；授權決定可做什麼。依據：identity / S05。':'比較 ARR 前，要核對涵蓋產品與期末日期。依據：metrics / S07、S08。')});
function hash(){const m=location.hash.match(/^#slide-(\d+)$/);if(m){tab('deck');index=Math.max(0,Math.min(D.slides.length-1,Number(m[1])-1));render()}else if(location.hash.startsWith('#source-'))source(location.hash.slice(8));else if(location.hash==='#wiki')tab('wiki');else if(location.hash==='#workflow')tab('workflow')}
window.addEventListener('hashchange',hash);render();hash();searchWiki('');
